const axios = require('axios')
const fs = require('fs').promises

/*********************************************************
 *
 * SETUP:
 *
 * Create a new directory e.g. code-samples
 * Copy this whole file and save to code-samples/threat_removal_instant.js
 * Copy 'USAGE:' code to code-samples/instant.js
 * Update code-samples/instant.js with your API KEY and paths for input and output
 * > cd code-samples
 * > npm install axios
 * > node instant.js
 *
 * USAGE:
 *
 * const threat_removal_async = require('./threat_removal_async')
 * threat_removal_async.start('${URL}',
 *     'ABC----YOUR_APIKEY----789',
 *     'input.pdf',
 *     'output.pdf',
 *     'application/pdf')
 * .then(({filename, metadata}) => {
 *     console.log(`Success: ${filename}`)
 *     console.log(metadata)
 * })
 * .catch(err => {
 *     if (!err.response || !err.response.data) {
 *         console.error(err.message)
 *     } else console.error('Response data:', err.response.data);
 * });
 *
 ********************************************************/
const STATUS_CHECK_INTERVAL = 1000
const promiseTimeout = (delay) => new Promise(resolve => setTimeout(resolve, delay))

exports.start = async (apiEndpointBase, apiKey, inputFilename, targetFilename, mimeType, convertFrom) => {

    const initResponse = await init(apiKey, apiEndpointBase, mimeType, convertFrom)
    await upload(initResponse.data.links.upload, inputFilename)

    const statusCheck = pollStatus(initResponse.data.links.status)
    let statusResponse = await statusCheck.next()
    while (!statusResponse.done) {
        await promiseTimeout(STATUS_CHECK_INTERVAL)
        statusResponse = await statusCheck.next()
    }
    const downloadResponse = await download(statusResponse.value.links.result)

    await fs.writeFile(targetFilename, downloadResponse.data)

    return { filename: targetFilename, metadata: statusResponse.value._metadata }
}

async function init(apiKey, apiEndpointBase, mimeType, convertFrom) {
    const headers = {
        'x-api-key': apiKey,
        'Content-Type': 'application/json'
    }
    const data = {
        'mime-type': mimeType
    }

    if (convertFrom) data.options = { conversion: { from: { "mime-type": convertFrom } } }

    return await axios({
        method: 'POST',
        url: apiEndpointBase + '/initiate',
        headers: headers,
        data: data
    })
}

async function upload(uploadLink, inputFilename) {
    const data = await fs.readFile(inputFilename)

    const response = await axios({
        method: uploadLink.method,
        headers: uploadLink.headers,
        url: uploadLink.url,
        maxContentLength: Math.max(20000, data.length),
        data: data
    })

    return response
}

async function* pollStatus(statusLink, etag) {
    let response = {}
    while (!response.data || !response.data.status || !response.data.status.complete) {
        response = await axios({
            validateStatus: status => status < 400 || status == 404,
            headers: Object.assign({ 'If-None-Match' : etag || '' }, statusLink.headers),
            url: statusLink.url,
            method: statusLink.method
        })

        if (response.status != 304) {
            if (response.data.status && response.data.status.complete && !response.data.status.success) {
                const error = new Error(response.data.error.message)
                error.code = response.data.error.code
                error.response = response.data
                throw error
            }

            statusLink = response.data.links.status
        }
        etag = response.headers['etag']
        yield response.data
    }

    return response.data
}

async function download(resultLink) {
    return await axios.request({
        url: resultLink.url,
        method: resultLink.method,
        headers: resultLink.headers,
        maxContentLength: Math.max(20000, resultLink.fileSize),
        responseType: 'arraybuffer'
    })
}

import shutil
import time

import requests

# SETUP:
# This code sample requires the requests library,
# install this using pip:-
# > pip install requests
#
# USAGE:
# start(
#    '${URL}',
#    'ABC----YOUR_APIKEY----789',
#    'input.pdf',
#    'output.pdf',
#    'application/pdf'
# )


def start(api_endpoint_base, api_key, filename, target_filename, mime_type, timeout=600, convert_from=None):
    response = _initiate(api_endpoint_base, api_key, mime_type, convert_from)
    response.raise_for_status()
    init_data = response.json()

    response = _upload(filename, init_data['links']['upload'])
    response.raise_for_status()

    result_link = _check_status_until_complete(init_data['links']['status'], timeout)

    response = _download(result_link)
    response.raise_for_status()

    with open(target_filename, 'wb') as target_file:
        shutil.copyfileobj(response.raw, target_file)


def _initiate(api_endpoint_base, api_key, mime_type, convert_from=None):
    data = {'mime-type': mime_type}
    headers = {'x-api-key': api_key, 'Content-Type': 'application/json'}
    if convert_from:
        data['options'] = {'conversion': {'from': {'mime-type': convert_from}}}

    return requests.post(f'{api_endpoint_base}/initiate', json=data, headers=headers)


def _upload(filename, upload_link):
    with open(filename, 'rb') as file:
        return requests.request(
            method=upload_link['method'], url=upload_link['url'], headers=upload_link['headers'], data=file
        )


def _check_status(link):
    return requests.request(method=link['method'], url=link['url'], headers=link['headers'])


def _check_status_until_complete(link, timeout):
    for elapsed in range(1, timeout + 1):
        response = _check_status(link)
        if response.status_code not in [404, 304, 429]:
            response.raise_for_status()
            status_data = response.json()
            if status_data['status']['complete']:
                if status_data['status']['success']:
                    result_link = status_data['links']['result']
                    break
                raise Exception(status_data.get('error', {}).get('name', 'Error during Everfox CDR'))

            link = status_data['links']['status']
            link['headers']['If-None-Match'] = response.headers.get('etag', None)
        if elapsed >= timeout:
            raise Exception('Timeout during Everfox CDR')
        time.sleep(1)
    return result_link


def _download(link):
    return requests.request(method=link['method'], url=link['url'], headers=link['headers'], stream=True)
